from pathlib import Path

path = Path("genesis/benchmark_execution.py")
text = path.read_text(encoding="utf-8")

anchor = '''    @classmethod\n    def _execution_readiness(cls, benchmark_id: str) -> dict[str, Any]:\n'''
method = '''    @classmethod\n    def _working_memory(\n        cls,\n        benchmark_id: str,\n        latest: GenesisTask | None,\n        readiness: dict[str, Any],\n    ) -> dict[str, Any]:\n        \"\"\"Keep the benchmark lane focused on current progress and localized evidence.\"\"\"\n        generation = cls._runner_generation(latest) if latest is not None else 0\n        state = latest.state if latest is not None else \"not_started\"\n        last_failure = \"\"\n        if latest is not None:\n            last_failure = str(latest.last_error or \"\").strip()\n            if not last_failure and latest.failure_history:\n                last_failure = str(latest.failure_history[-1].get(\"error\") or \"\").strip()\n        missing = tuple(str(item) for item in readiness.get(\"missing\", [])[:16])\n        exhausted = generation >= cls.MAX_RUNNER_INTEGRATION_GENERATIONS and latest is not None\n        if exhausted and benchmark_id not in cls.EVIDENCE_ADAPTER_BENCHMARKS:\n            selected_skill = \"engineering_assistance\"\n        elif exhausted and not bool(readiness.get(\"ready\")):\n            selected_skill = \"external_execution_readiness\"\n        elif exhausted:\n            selected_skill = \"benchmark_evidence_staging\"\n        else:\n            selected_skill = \"benchmark_runner_integration\"\n        return {\n            \"benchmark_id\": benchmark_id,\n            \"runner_generation\": generation,\n            \"runner_state\": state,\n            \"last_failure\": last_failure[:500],\n            \"missing_prerequisites\": missing,\n            \"selected_skill\": selected_skill,\n            \"strategy_change_required\": generation > 0,\n        }\n\n'''
if text.count(anchor) != 1:
    raise SystemExit("working-memory insertion anchor mismatch")
text = text.replace(anchor, method + anchor, 1)

old = '''        existing = self._runner_tasks(benchmark_id)\n        latest = max(existing, key=self._runner_generation) if existing else None\n        if latest is not None and latest.state not in self.TERMINAL_RUNNER_STATES:\n            return {\n                \"status\": \"runner_work_queued\",\n                \"benchmark_id\": benchmark_id,\n                \"task_id\": latest.task_id,\n                \"created\": False,\n                \"work_generation\": self._runner_generation(latest),\n                \"runner_state\": latest.state,\n            }\n\n        readiness = self._execution_readiness(benchmark_id)\n'''
new = '''        existing = self._runner_tasks(benchmark_id)\n        latest = max(existing, key=self._runner_generation) if existing else None\n        readiness = self._execution_readiness(benchmark_id)\n        working_memory = self._working_memory(benchmark_id, latest, readiness)\n        if latest is not None and latest.state not in self.TERMINAL_RUNNER_STATES:\n            return {\n                \"status\": \"runner_work_queued\",\n                \"benchmark_id\": benchmark_id,\n                \"task_id\": latest.task_id,\n                \"created\": False,\n                \"work_generation\": self._runner_generation(latest),\n                \"runner_state\": latest.state,\n                \"working_memory\": working_memory,\n            }\n\n'''
if text.count(old) != 1:
    raise SystemExit("runner-task readiness anchor mismatch")
text = text.replace(old, new, 1)

text = text.replace('''                    \"engineering_assistance_required\": True,\n                    \"owner_action_required\": False,\n                }\n''', '''                    \"engineering_assistance_required\": True,\n                    \"owner_action_required\": False,\n                    \"working_memory\": working_memory,\n                }\n''', 1)
text = text.replace('''                    \"last_work_generation\": self._runner_generation(latest),\n                    \"owner_action_required\": True,\n                }\n''', '''                    \"last_work_generation\": self._runner_generation(latest),\n                    \"owner_action_required\": True,\n                    \"working_memory\": working_memory,\n                }\n''', 1)

old = '''        if generation > 1:\n            objective += (\n                f\" This is integration generation {generation}. Do not repeat the previous implementation approach; \"\n                \"use different repository evidence, adapter boundaries, or execution strategy while preserving all validation rules.\"\n            )\n            if prior_failure:\n                objective += f\" Previous bounded attempt ended with: {prior_failure[:500]}\"\n'''
new = '''        if generation > 1:\n            objective += (\n                f\" This is integration generation {generation}. Do not repeat the previous implementation approach; \"\n                \"use different repository evidence, adapter boundaries, or execution strategy while preserving all validation rules.\"\n            )\n            if prior_failure:\n                objective += f\" Previous bounded attempt ended with: {prior_failure[:500]}\"\n        objective += f\" Current bounded working memory: {json.dumps(working_memory, sort_keys=True)}\"\n'''
if text.count(old) != 1:
    raise SystemExit("objective working-memory anchor mismatch")
text = text.replace(old, new, 1)

old = '''                \"work_generation\": generation,\n                \"strategy_change_required\": generation > 1,\n            },\n'''
new = '''                \"work_generation\": generation,\n                \"strategy_change_required\": generation > 1,\n                \"working_memory\": working_memory,\n            },\n'''
if text.count(old) != 1:
    raise SystemExit("payload working-memory anchor mismatch")
text = text.replace(old, new, 1)

old = '''            \"work_generation\": generation,\n            \"runner_state\": child.state,\n        }\n'''
new = '''            \"work_generation\": generation,\n            \"runner_state\": child.state,\n            \"working_memory\": working_memory,\n        }\n'''
if text.count(old) != 1:
    raise SystemExit("result working-memory anchor mismatch")
