path.write_text(text, encoding="utf-8")


tests = Path("tests/test_benchmark_execution.py")
test_text = tests.read_text(encoding="utf-8")
append = '''\n\ndef test_runner_task_carries_bounded_working_memory_snapshot(tmp_path: Path) -> None:\n    task = make_task(tmp_path, \"new_frontier_benchmark\")\n    planner = BenchmarkExecutionPlanner(tmp_path)\n    result = planner.advance(task)\n    memory = result[\"working_memory\"]\n    assert memory[\"runner_generation\"] == 0\n    assert memory[\"runner_state\"] == \"not_started\"\n    assert memory[\"selected_skill\"] == \"benchmark_runner_integration\"\n    child = planner.queue.get(result[\"task_id\"])\n    assert child is not None\n    assert child.payload[\"working_memory\"] == memory\n    assert \"Current bounded working memory:\" in child.objective\n\n\ndef test_exhausted_unknown_runner_localizes_next_skill_to_engineering_assistance(tmp_path: Path) -> None:\n    task = make_task(tmp_path, \"new_frontier_benchmark\")\n    planner = BenchmarkExecutionPlanner(tmp_path)\n    for _ in range(planner.MAX_RUNNER_INTEGRATION_GENERATIONS):\n        attempt = planner.advance(task)\n        child = planner.queue.get(attempt[\"task_id\"])\n        assert child is not None\n        planner.queue.transition(child.task_id, \"assigned\", module_id=\"genesis.coding\")\n        planner.queue.transition(child.task_id, \"running\", module_id=\"genesis.coding\")\n        planner.queue.transition(child.task_id, \"failed\", module_id=\"genesis.coding\", error=\"localized runner failure\")\n        planner.queue.transition(child.task_id, \"quarantined\", module_id=\"genesis.coding\")\n    result = planner.advance(task)\n    memory = result[\"working_memory\"]\n    assert memory[\"selected_skill\"] == \"engineering_assistance\"\n    assert memory[\"last_failure\"] == \"localized runner failure\"\n    assert memory[\"runner_generation\"] == planner.MAX_RUNNER_INTEGRATION_GENERATIONS\n\n\ndef test_terminal_readiness_working_memory_localizes_missing_prerequisites(tmp_path: Path, monkeypatch) -> None:\n    for name in BenchmarkExecutionPlanner.TERMINAL_BENCH_ENV:\n        monkeypatch.delenv(name, raising=False)\n    monkeypatch.setattr(\"genesis.benchmark_execution.shutil.which\", lambda _: None)\n    task = make_task(tmp_path)\n    planner = BenchmarkExecutionPlanner(tmp_path)\n    for _ in range(planner.MAX_RUNNER_INTEGRATION_GENERATIONS):\n        attempt = planner.advance(task)\n        quarantine(planner.queue, attempt[\"task_id\"])\n    result = planner.advance(task)\n    memory = result[\"working_memory\"]\n    assert memory[\"selected_skill\"] == \"external_execution_readiness\"\n    assert \"harbor_cli\" in memory[\"missing_prerequisites\"]\n    assert \"GENESIS_BENCHMARK_MODEL\" in memory[\"missing_prerequisites\"]\n'''
if "test_runner_task_carries_bounded_working_memory_snapshot" not in test_text:
    tests.write_text(test_text.rstrip() + append + "\n", encoding="utf-8")
